const ChargeRequest = z.object({
  orderId: z.string().uuid(),
  paymentToken: z.string().regex(/^tok_[A-Za-z0-9]{24}$/),
  idempotencyKey: z.string().uuid(),
}).strict();

export async function charge(req: Request): Promise<Response> {
  const body = rejectPan(await req.text());
  const input = ChargeRequest.parse(JSON.parse(body));
  const order = await orders.get(input.orderId);
  const result = await processor.charge({ token: input.paymentToken, amount: order.total, idempotencyKey: input.idempotencyKey });
  audit({ actor: 'checkout', action: 'charge', target: `order:${order.id}`, detail: { status: result.status, last4: result.last4 } });
  return Response.json({ status: result.status });
}
